715	    private sortModelsBySovereignPriority(models: string[]): string[] {
716	        if (models.length === 0) return [];
717	        const unique = Array.from(new Set(models.filter(Boolean)));
718	        
719	        // The first model is considered the "preferred" target, keep it at [0] if it's healthy/available
720	        const preferred = unique[0];
721	        const rest = unique.slice(1);
722	
723	        const local: string[] = [];
724	        const cloudflareHf: string[] = [];
725	        const others: string[] = [];
726	
727	        for (const m of rest) {
728	            if (m.startsWith('huggingface:') || m.startsWith('@cf/') || m.includes('cloudflare') || m.startsWith('fireworks:') || m.startsWith('openrouter:')) {
729	                cloudflareHf.push(m);
730	            } else if (m.startsWith('gemini:') || m.includes('openai') || m.includes('anthropic') || m.includes(':cloud')) {
731	                others.push(m);
732	            } else {
733	                // Determine via omission: Ollama / Local Substrate
734	                local.push(m);
735	            }
736	        }
737	
738	        // Optimal Cloud-First/Local-Fallback: 
739	        // 1. Preferred target
740	        // 2. Other Clouds / APIs
741	        // 3. Local Substrate
742	        // 4. Guaranteed universal Local Fallback
743	        const result = [preferred, ...others, ...cloudflareHf, ...local];
744	        
745	        // Ensure the absolute sovereign local fallback is pushed to the very end if not already
746	        const finalFallback = this.config.localFallbackModel;
747	        const fallbackFiltered = result.filter(m => m !== finalFallback);
748	        fallbackFiltered.push(finalFallback);
749	
750	        return Array.from(new Set(fallbackFiltered));
751	    }
