765	    private findWorkingModel(preferred: string, fallbacks: string[], taskType: TaskType = 'text'): string {
766	        const rawList = [preferred, ...fallbacks, this.config.localFallbackModel];
767	        const unique = Array.from(new Set(rawList.filter(Boolean)));
768	        
769	        // ðŸ§¬ Nervous System v2: Scored Routing (Phase 9)
770	        const allModels = this.rolodex?.getAllModels() || [];
771	        const scored = unique
772	            .filter(mId => this.isModelAvailableAndHealthy(mId) && this.isModalityCompatible(mId, taskType))
773	            .map(mId => {
774	                // Find matching model in rolodex
775	                const mData = allModels.find(m => m.id === mId || `${m.provider}:${m.id}` === mId);
776	                const rep = mData?.reputation ?? 1.0;
777	                const avgLatency = mData?.avgLatencyMs ?? 500;
778	                const expectedLatency = Math.max(avgLatency, 50);
779	                
780	                // ðŸ§¬ Phase 108: Explicit Decision Weighting
781	                // score = (reputation weight) / log(1 + latency)
782	                const score = rep / Math.log(1 + expectedLatency);
783	                return { id: mId, score };
784	            })
785	            .sort((a, b) => b.score - a.score);
786	
787	        const sorted = scored.map(s => s.id);
788	        if (sorted.length === 0) return this.config.localFallbackModel;
789	
790	        // ðŸ§¬ Nervous System v2: Îµ-greedy Adaptive Exploration (Phase 9)
791	        const epsilon = 0.25 - (this.lastConfidence * 0.20);
792	        if (Math.random() < epsilon && sorted.length > 1) {
793	            const randomIndex = Math.floor(Math.random() * (sorted.length - 1)) + 1; // Pick non-primary
794	            const exploredModel = sorted[randomIndex];
795	            logger.info({ model: exploredModel, epsilon, taskType }, 'ðŸ§¬ CNS Îµ-greedy: Exploration triggered');
796	            return exploredModel;
