        else {
            const yao = this.classifyYao(taskType || '', complexity);

                    [this.config.masterLocalModel, 'deepseek-coder:33b-instruct-q4_K_M', 'deepseek-r1:8b', this.config.localFallbackModel],
                    finalTaskType
                );
                decision = {
                    model,
                    complexity: 'Yang',
                    tier: 'Master',
                    reasoning: 'Stage 4 (Cloud/Deep) - Deep Path (Sovereignty) activated for heavy structural manipulation',
