                    fallbackUsed: false,
                    timestamp: routeStartTime
                };
            } else if (complexity === 'YinYang') {
                const model = this.findWorkingModel(this.config.midPathModel, [this.config.codingHeavyModel, this.config.localFallbackModel], finalTaskType);
                decision = {
