1	import { Server } from "@modelcontextprotocol/sdk/server/index.js";
2	import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
3	import {
4	  CallToolRequestSchema,
5	  ListToolsRequestSchema,
6	} from "@modelcontextprotocol/sdk/types.js";
7	import { ToolRegistry } from "./ToolRegistry.js";
8	import { ModelClient } from "./clients/ModelClient.js";
9	import { createLogger } from "./utils/logger.js";
10	import { TrainingCollector } from "./utils/TrainingCollector.js";
11	import { CompressionEngine } from "./utils/CompressionEngine.js";
12	import dotenv from "dotenv";
13	
14	dotenv.config();
15	
16	const logger = createLogger('MCPBridge');
17	const registry = new ToolRegistry();
18	const modelClient = new ModelClient();
19	const training = TrainingCollector.getInstance();
20	const compressor = CompressionEngine.getInstance();
21	
22	/**
23	 * MCP Server implementation for POG2 Sovereign.
24	 * This bridge allows external orchestrators (like Antigravity) to
25	 * execute POG2 internal tools and leverage local Ollama model selection.
26	 */
27	async function main() {
28	  const server = new Server(
29	    {
30	      name: "pog2-sovereign-bridge",
31	      version: "1.0.0",
32	    },
33	    {
34	      capabilities: {
35	        tools: {},
36	      },
37	    }
38	  );
39	
